import React, { useState, useEffect } from "react";
import Product from "./Product"; // Import component từ TASK-05

// Kho dữ liệu ảo 20 sản phẩm công nghệ
const mockProductsFromMySQL = [
  { id: 1, name: "Điện thoại iPhone 15 Pro Max 256GB", price: 29500000, category: "PC_Gaming", image_url: "", percent_off: 10 },
  { id: 2, name: "Laptop MacBook Air M2 8GB/256GB", price: 24990000, category: "Laptop", image_url: "", percent_off: 0 },
  { id: 3, name: "Điện thoại Samsung Galaxy S24 Ultra", price: 26990000, category: "PC_Gaming", image_url: "", percent_off: 15 },
  { id: 4, name: "Laptop Asus Vivobook 14 X1404ZA", price: 14290000, category: "Laptop", image_url: "", percent_off: 5 },
  { id: 5, name: "Máy tính bảng iPad Air 5 M1 Wifi", price: 15490000, category: "LinhKien", image_url: "", percent_off: 8 },
  { id: 6, name: "Tai nghe Bluetooth AirPods Pro Gen 2", price: 5690000, category: "GamingGear", image_url: "", percent_off: 12 },
  { id: 7, name: "Đồng hồ thông minh Apple Watch Series 9", price: 9890000, category: "GamingGear", image_url: "", percent_off: 0 },
  { id: 8, name: "Điện thoại Xiaomi Redmi Note 13 Pro", price: 6490000, category: "PC_VanPhong", image_url: "", percent_off: 10 },
  { id: 9, name: "Laptop Lenovo Ideapad Slim 3", price: 12890000, category: "Laptop", image_url: "", percent_off: 0 },
  { id: 10, name: "Chuột không dây Logitech MX Master 3S", price: 2350000, category: "GamingGear", image_url: "", percent_off: 5 },
  { id: 11, name: "Bàn phím cơ ASUS ROG Strix Scope", price: 3150000, category: "GamingGear", image_url: "", percent_off: 20 },
  { id: 12, name: "Điện thoại OPPO Reno11 5G", price: 9990000, category: "PC_VanPhong", image_url: "", percent_off: 0 },
  { id: 13, name: "Máy tính bảng Samsung Galaxy Tab S9 FE", price: 10490000, category: "LinhKien", image_url: "", percent_off: 7 },
  { id: 14, name: "Tai nghe Chụp Tai Sony WH-1000XM5", price: 6990000, category: "GamingGear", image_url: "", percent_off: 15 },
  { id: 15, name: "Củ sạc nhanh Anker GaNPrime 65W", price: 850000, category: "LinhKien", image_url: "", percent_off: 0 },
  { id: 16, name: "Laptop Dell Inspiron 14 5430", price: 17990000, category: "Laptop", image_url: "", percent_off: 10 },
  { id: 17, name: "Đồng hồ Samsung Galaxy Watch6 LTE", price: 6490000, category: "GamingGear", image_url: "", percent_off: 18 },
  { id: 18, name: "Loa Bluetooth JBL Charge 5", price: 3650000, category: "GamingGear", image_url: "", percent_off: 5 },
  { id: 19, name: "Pin sạc dự phòng Baseus 20000mAh 22.5W", price: 450000, category: "LinhKien", image_url: "", percent_off: 0 },
  { id: 20, name: "Màn hình Gaming MSI Optix 24 inch", price: 3290000, category: "ManHinh", image_url: "", percent_off: 12 }
];

// Mảng danh sách menu giống hệt trong ảnh của bạn
const menuCategories = [
  { id: "PC_ChuyenDung", name: "PC Chuyên Dụng" },
  { id: "PC_GiaRe", name: "PC Giá Rẻ" },
  { id: "PC_Gaming", name: "PC Gaming, Học Tập" },
  { id: "PC_VanPhong", name: "PC Văn Phòng" },
  { id: "Laptop", name: "Laptop - Notebook" },
  { id: "CPU", name: "CPU - Bộ Vi Xử Lý" },
  { id: "Mainboard", name: "Mainboard - Bo Mạch Chủ" },
  { id: "VGA", name: "VGA - Card Màn Hình" },
  { id: "LinhKien", name: "Linh Kiện Máy Tính" },
  { id: "ManHinh", name: "Màn Hình Máy Tính" },
  { id: "O_Cung", name: "HDD - SSD - NAS" },
  { id: "TanNhiet", name: "Tản Nhiệt Cooling" },
  { id: "GamingGear", name: "Gaming Gear" }
];

function ProductList() {
  const [products, setProducts] = useState([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [category, setCategory] = useState("");
  const [loading, setLoading] = useState(false);

  const filterMockData = () => {
    setLoading(true);
    const filtered = mockProductsFromMySQL.filter((item) => {
      const matchCategory = category === "" || item.category === category;
      const matchSearch = item.name.toLowerCase().includes(searchTerm.toLowerCase());
      return matchCategory && matchSearch;
    });
    setProducts(filtered);
    setLoading(false);
  };

  useEffect(() => {
    filterMockData();
  }, [category]);

  const handleSearchSubmit = (e) => {
    e.preventDefault();
    filterMockData();
  };

  return (
    <div className="container-fluid mt-4 mb-5 px-4">
      {/* --- THANH TÌM KIẾM PHÍA TRÊN --- */}
      <div className="row justify-content-center mb-4">
        <div className="col-md-6">
          <form onSubmit={handleSearchSubmit} className="d-flex gap-2">
            <input
              type="text"
              className="form-control shadow-sm"
              placeholder="🔍 Nhập tên sản phẩm công nghệ cần tìm..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
            <button type="submit" className="btn btn-dark px-4">Tìm</button>
          </form>
        </div>
      </div>

      {/* --- BỐ CỤC CHÍNH: SIDEBAR TRÁI & NỘI DUNG PHẢI --- */}
      <div className="row">
        
        {/* === DANH SÁCH DANH MỤC BÊN TAY TRÁI (SIDEBAR) === */}
        <div className="col-md-3 mb-4">
          <div className="card shadow-sm border-0 rounded-3 overflow-hidden">
            <div className="list-group list-group-flush">
              {/* Nút hiển thị tất cả */}
              <button
                type="button"
                className={`list-group-item list-group-item-action text-start fw-bold py-3 ${category === "" ? "active bg-dark text-white" : ""}`}
                onClick={() => setCategory("")}
              >
                🏠 Tất cả sản phẩm
              </button>
              
              {/* Duyệt mảng hiển thị các danh mục như ảnh yêu cầu */}
              {menuCategories.map((menu) => (
                <button
                  key={menu.id}
                  type="button"
                  className={`list-group-item list-group-item-action text-start py-2 d-flex justify-content-between align-items-center ${category === menu.id ? "active bg-dark text-white" : ""}`}
                  onClick={() => setCategory(menu.id)}
                >
                  <span>🔹 {menu.name}</span>
                  <small className="text-muted">➔</small>
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* === LƯỚI HIỂN THỊ SẢN PHẨM BÊN TAY PHẢI === */}
        <div className="col-md-9">
          <h3 className="fw-bold mb-4">
            {category === "" ? "Tất cả sản phẩm nổi bật" : `Danh mục: ${menuCategories.find(m => m.id === category)?.name}`}
          </h3>

          {loading ? (
            <div className="text-center mt-4">
              <p className="text-muted fs-5">Đang xử lý dữ liệu...</p>
            </div>
          ) : (
            <div className="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4">
              {products.length > 0 ? (
                products.map((item) => (
                  <Product key={item.id} data={item} />
                ))
              ) : (
                <div className="col-12 text-center mt-4">
                  <p className="text-muted fs-5">Không tìm thấy sản phẩm nào trong mục này.</p>
                </div>
              )}
            </div>
          )}
        </div>

      </div>
    </div>
  );
}

export default ProductList;
